import React from 'react';

const DeliveryHistory = () => {
    return (
        <div>
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Delivery History</h1>
            <p className="text-gray-500 mt-1">View your completed deliveries.</p>
            <p className="text-center text-gray-500 py-12">Delivery history will appear here.</p>
        </div>
    );
};

export default DeliveryHistory;
